package com.college.erp.util;
import java.security.*; import java.util.Base64;
public final class PasswordUtil { private PasswordUtil(){} public static String hash(String password){try{byte[] salt=new byte[16];new SecureRandom().nextBytes(salt);MessageDigest md=MessageDigest.getInstance("SHA-256");md.update(salt);return Base64.getEncoder().encodeToString(salt)+":"+Base64.getEncoder().encodeToString(md.digest(password.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}} public static boolean verify(String password,String stored){try{String[] p=stored.split(":");if(p.length!=2)return false;byte[] salt=Base64.getDecoder().decode(p[0]);byte[] expected=Base64.getDecoder().decode(p[1]);MessageDigest md=MessageDigest.getInstance("SHA-256");md.update(salt);return MessageDigest.isEqual(expected,md.digest(password.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(Exception e){return false;}} }
